template<typename Tunnel = Tunnel, typename LazyPlugin = LazyPlugin<Tunnel>>

class TunnelServiceImpl final : public rpc::tunnel::TunnelService::Service {
public:

    TunnelServiceImpl(LazyPlugin& lazy_plugin) : _lazy_plugin(lazy_plugin) {}



    template<typename ResponseType>
    void fillResponseWithResult(ResponseType* response, mavsdk::Tunnel::Result& result) const
    {
        auto rpc_result = translateToRpcResult(result);

        auto* rpc_tunnel_result = new rpc::tunnel::TunnelResult();
        rpc_tunnel_result->set_result(rpc_result);
        std::stringstream ss;
        ss << result;
        rpc_tunnel_result->set_result_str(ss.str());

        response->set_allocated_tunnel_result(rpc_tunnel_result);
    }




    static std::unique_ptr<rpc::tunnel::TunnelMessage> translateToRpcTunnelMessage(const mavsdk::Tunnel::TunnelMessage &tunnel_message)
    {
        auto rpc_obj = std::make_unique<rpc::tunnel::TunnelMessage>();


            
        rpc_obj->set_target_system(tunnel_message.target_system);
            
        
            
        rpc_obj->set_target_component(tunnel_message.target_component);
            
        
            
        rpc_obj->set_payload_type(tunnel_message.payload_type);
            
        
            
        rpc_obj->set_payload_length(tunnel_message.payload_length);
            
        
            
        for (const auto& elem : tunnel_message.payload) {
            rpc_obj->add_payload(elem);
        }
            
        

        return rpc_obj;
    }

    static mavsdk::Tunnel::TunnelMessage translateFromRpcTunnelMessage(const rpc::tunnel::TunnelMessage& tunnel_message)
    {
        mavsdk::Tunnel::TunnelMessage obj;


            
        obj.target_system = tunnel_message.target_system();
            
        
            
        obj.target_component = tunnel_message.target_component();
            
        
            
        obj.payload_type = tunnel_message.payload_type();
            
        
            
        obj.payload_length = tunnel_message.payload_length();
            
        
            
                for (const auto& elem : tunnel_message.payload()) {
                    obj.payload.push_back(elem);
                }
            
        
        return obj;
    }




    static rpc::tunnel::TunnelResult::Result translateToRpcResult(const mavsdk::Tunnel::Result& result)
    {
        switch (result) {
            default:
                LogErr() << "Unknown result enum value: " << static_cast<int>(result);
            // FALLTHROUGH
            case mavsdk::Tunnel::Result::Unknown:
                return rpc::tunnel::TunnelResult_Result_RESULT_UNKNOWN;
            case mavsdk::Tunnel::Result::Success:
                return rpc::tunnel::TunnelResult_Result_RESULT_SUCCESS;
            case mavsdk::Tunnel::Result::NoSystem:
                return rpc::tunnel::TunnelResult_Result_RESULT_NO_SYSTEM;
            case mavsdk::Tunnel::Result::ConnectionError:
                return rpc::tunnel::TunnelResult_Result_RESULT_CONNECTION_ERROR;
            case mavsdk::Tunnel::Result::Busy:
                return rpc::tunnel::TunnelResult_Result_RESULT_BUSY;
            case mavsdk::Tunnel::Result::Timeout:
                return rpc::tunnel::TunnelResult_Result_RESULT_TIMEOUT;
            case mavsdk::Tunnel::Result::InvalidArgument:
                return rpc::tunnel::TunnelResult_Result_RESULT_INVALID_ARGUMENT;
            case mavsdk::Tunnel::Result::Unsupported:
                return rpc::tunnel::TunnelResult_Result_RESULT_UNSUPPORTED;
            case mavsdk::Tunnel::Result::Failed:
                return rpc::tunnel::TunnelResult_Result_RESULT_FAILED;
        }
    }

    static mavsdk::Tunnel::Result translateFromRpcResult(const rpc::tunnel::TunnelResult::Result result)
    {
        switch (result) {
            default:
                LogErr() << "Unknown result enum value: " << static_cast<int>(result);
            // FALLTHROUGH
            case rpc::tunnel::TunnelResult_Result_RESULT_UNKNOWN:
                return mavsdk::Tunnel::Result::Unknown;
            case rpc::tunnel::TunnelResult_Result_RESULT_SUCCESS:
                return mavsdk::Tunnel::Result::Success;
            case rpc::tunnel::TunnelResult_Result_RESULT_NO_SYSTEM:
                return mavsdk::Tunnel::Result::NoSystem;
            case rpc::tunnel::TunnelResult_Result_RESULT_CONNECTION_ERROR:
                return mavsdk::Tunnel::Result::ConnectionError;
            case rpc::tunnel::TunnelResult_Result_RESULT_BUSY:
                return mavsdk::Tunnel::Result::Busy;
            case rpc::tunnel::TunnelResult_Result_RESULT_TIMEOUT:
                return mavsdk::Tunnel::Result::Timeout;
            case rpc::tunnel::TunnelResult_Result_RESULT_INVALID_ARGUMENT:
                return mavsdk::Tunnel::Result::InvalidArgument;
            case rpc::tunnel::TunnelResult_Result_RESULT_UNSUPPORTED:
                return mavsdk::Tunnel::Result::Unsupported;
            case rpc::tunnel::TunnelResult_Result_RESULT_FAILED:
                return mavsdk::Tunnel::Result::Failed;
        }
    }




    grpc::Status SendTunnelMessage(
        grpc::ServerContext* /* context */,
        const rpc::tunnel::SendTunnelMessageRequest* request,
        rpc::tunnel::SendTunnelMessageResponse* response) override
    {
        if (_lazy_plugin.maybe_plugin() == nullptr) {
            
            if (response != nullptr) {
                auto result = mavsdk::Tunnel::Result::NoSystem;
                fillResponseWithResult(response, result);
            }
            
            return grpc::Status::OK;
        }

        if (request == nullptr) {
            LogWarn() << "SendTunnelMessage sent with a null request! Ignoring...";
            return grpc::Status::OK;
        }
            
        
            
        
            
        
            
        
            
        std::vector<mavsdk::Tunnel::std::byte> payload_vec;
        for (const auto& elem : request->payload()) {
            payload_vec.push_back(elem);
        }
            
        
        auto result = _lazy_plugin.maybe_plugin()->send_tunnel_message(request->target_system(), request->target_component(), request->payload_type(), request->payload_length(), payload_vec);
        

        
        if (response != nullptr) {
            fillResponseWithResult(response, result);
        }
        

        return grpc::Status::OK;
    }

    grpc::Status SubscribeTunnelMessage(grpc::ServerContext* /* context */, const mavsdk::rpc::tunnel::SubscribeTunnelMessageRequest* /* request */, grpc::ServerWriter<rpc::tunnel::TunnelMessageResponse>* writer) override
    {
        if (_lazy_plugin.maybe_plugin() == nullptr) {
            
            return grpc::Status::OK;
        }

        auto stream_closed_promise = std::make_shared<std::promise<void>>();
        auto stream_closed_future = stream_closed_promise->get_future();
        register_stream_stop_promise(stream_closed_promise);

        auto is_finished = std::make_shared<bool>(false);
        auto subscribe_mutex = std::make_shared<std::mutex>();

        const mavsdk::Tunnel::TunnelMessageHandle handle = _lazy_plugin.maybe_plugin()->subscribe_tunnel_message(
            [this, &writer, &stream_closed_promise, is_finished, subscribe_mutex, &handle](const mavsdk::Tunnel::TunnelMessage tunnel_message) {

            rpc::tunnel::TunnelMessageResponse rpc_response;
        
            rpc_response.set_allocated_tunnel_message(translateToRpcTunnelMessage(tunnel_message).release());
        

        

            std::unique_lock<std::mutex> lock(*subscribe_mutex);
            if (!*is_finished && !writer->Write(rpc_response)) {
                
                _lazy_plugin.maybe_plugin()->unsubscribe_tunnel_message(handle);
                
                *is_finished = true;
                unregister_stream_stop_promise(stream_closed_promise);
                stream_closed_promise->set_value();
            }
        });

        stream_closed_future.wait();
        std::unique_lock<std::mutex> lock(*subscribe_mutex);
        *is_finished = true;

        return grpc::Status::OK;
    }


    void stop() {
        _stopped.store(true);
        std::lock_guard<std::mutex> lock(_stream_stop_mutex);
        for (auto& prom : _stream_stop_promises) {
            if (auto handle = prom.lock()) {
                handle->set_value();
            }
        }
    }

private:
    void register_stream_stop_promise(std::weak_ptr<std::promise<void>> prom) {
        // If we have already stopped, set promise immediately and don't add it to list.
        if (_stopped.load()) {
            if (auto handle = prom.lock()) {
                handle->set_value();
            }
        } else {
            std::lock_guard<std::mutex> lock(_stream_stop_mutex);
            _stream_stop_promises.push_back(prom);
        }
    }

    void unregister_stream_stop_promise(std::shared_ptr<std::promise<void>> prom) {
        std::lock_guard<std::mutex> lock(_stream_stop_mutex);
        for (auto it = _stream_stop_promises.begin(); it != _stream_stop_promises.end(); /* ++it */) {
            if (it->lock() == prom) {
                it = _stream_stop_promises.erase(it);
            } else {
                ++it;
            }
        }
    }


    LazyPlugin& _lazy_plugin;

    std::atomic<bool> _stopped{false};
    std::mutex _stream_stop_mutex{};
    std::vector<std::weak_ptr<std::promise<void>>> _stream_stop_promises {};
};

